import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.Cji8e4wq.js";const g=JSON.parse('{"title":"Releasing a beta","description":"","frontmatter":{},"headers":[],"relativePath":"docs/releasing.md","filePath":"docs/releasing.md"}'),n={name:"docs/releasing.md"};function i(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="releasing-a-beta" tabindex="-1">Releasing a beta <a class="header-anchor" href="#releasing-a-beta" aria-label="Permalink to &quot;Releasing a beta&quot;">​</a></h1><p>Coach Poulpy is in beta. A release is a GitHub pre-release with the Android APK attached, made by one button and no agent.</p><h2 id="the-version" tabindex="-1">The version <a class="header-anchor" href="#the-version" aria-label="Permalink to &quot;The version&quot;">​</a></h2><p>The version people see (Settings, &quot;Version 0.1.0&quot;) is the one line in <a href="https://github.com/tkint/coach-poulpy/blob/main/VERSION" target="_blank" rel="noreferrer"><code>VERSION</code></a> at the repository root. Android reads it for <code>versionName</code> and iOS gets it as <code>MARKETING_VERSION</code>, so there is nowhere else to change it. It is three numbers, like <code>0.2.0</code>; while in beta it stays <code>0.x.y</code>.</p><h2 id="cut-a-release" tabindex="-1">Cut a release <a class="header-anchor" href="#cut-a-release" aria-label="Permalink to &quot;Cut a release&quot;">​</a></h2><ol><li>Raise <code>VERSION</code> in a pull request (<code>chore/release-0.2.0</code>) and merge it once CI is green.</li><li>On GitHub, open <strong>Actions &gt; Release &gt; Run workflow</strong>, keep the branch <code>main</code>, and run it.</li><li>A few minutes later the <strong>Releases</strong> page has a pre-release <code>v0.2.0</code> with <code>coach-poulpy-v0.2.0.apk</code> and notes listing the merged pull requests since the last one.</li><li>On a phone, download the APK from that page and install it over the old one; the phone&#39;s data is kept.</li></ol><p>The workflow stops with a message, and publishes nothing, if <code>VERSION</code> is not three numbers, if the tag for that version already exists (raise <code>VERSION</code> first), or if the signing key secrets are missing (see the README, &quot;The signing key&quot;).</p><h2 id="what-a-release-does-not-do-yet" tabindex="-1">What a release does not do yet <a class="header-anchor" href="#what-a-release-does-not-do-yet" aria-label="Permalink to &quot;What a release does not do yet&quot;">​</a></h2><ul><li><strong>iPhone:</strong> no file is attached. A phone build needs an Apple Developer account and signing; until then iOS is built from Xcode (README).</li><li><strong>Debug build type:</strong> the APK is the same <code>assembleDebug</code> build CI makes, the one that has been run on phones. A smaller, minified <code>assembleRelease</code> build is a later step once it has been tried on a phone.</li><li><strong>Not a store release:</strong> the pre-release flag keeps it off the &quot;latest&quot; release, and nothing goes to Google Play or TestFlight.</li></ul>',9)])])}const p=a(n,[["render",i]]);export{g as __pageData,p as default};
